          right: { label: "Concessão × Oposição", text: "**Oposição (adversidade):** contrapõe ideias no mesmo plano — 'Estudou muito, **mas** não passou'. **Concessão:** admite um obstáculo que NÃO impede o resultado — '**Embora** tenha estudado pouco, passou'. Dica: concessão quebra a expectativa (o esperado seria não passar)." },
